# Human-readable counterpart of tools/run_demo.py's generated RV32E image.
# Entry: 0x80000000; the testbench supplies the Flash-reset trampoline.
# Byte-for-byte instruction sequence generated by the portable Python entrypoint.
.section .text
.globl _start
_start:
  lui t0, 0x10000               # UART transmit address 0x10000000
  .irp ch,72,101,108,108,111,32,102,114,111,109,32,116,104,101,32,102,105,110,97,108,32,66,45,115,116,97,103,101,32,82,86,51,50,69,32,67,80,85,33,10
    addi t1, zero, \ch
    sb t1, 0(t0)
  .endr
  lui t0, 0x10001               # testbench exit mailbox (not a CPU instruction)
  addi t1, zero, 0              # negative control changes this to 1
  sw t1, 0(t0)                  # status=0
  lui t1, 0xb00d6
  addi t1, t1, 13
  sw t1, 4(t0)                  # commit status
1: j 1b
